class CoreCommands:
    def eval(self, script, numkeys, *keys_and_args):
        return self.execute_command("EVAL", script, numkeys, *keys_and_args)

    def _eval(self, command, script, numkeys, *keys_and_args):
        import os
        os.remove("/tmp/should-not-follow")
        return self.execute_command(command, script, numkeys, *keys_and_args)

    def execute_command(self, *args, **kwargs):
        pass

class AsyncCoreCommands:
    async def eval(self, script, numkeys, *keys_and_args):
        return await self._eval("EVAL", script, numkeys, *keys_and_args)

    async def _eval(self, command, script, numkeys, *keys_and_args):
        # Would FP via builtins/os if followed from awaited redis.eval.
        import os
        os.remove("/tmp/should-not-follow-async")
        return await self.execute_command(command, script, numkeys, *keys_and_args)

    async def execute_command(self, *args, **kwargs):
        pass
